```svelte file=lib/OtherTimes.svelte
<script>
  import { Section, List, ListRow, Action } from 'design';
  import Clock from 'phosphor-svelte/lib/Clock';
  import Check from 'phosphor-svelte/lib/Check';
  import { booking } from './booking.svelte.js';

  const slots = [
    { time: '5:45 pm', seat: 'Heated patio table', note: 'Early for Mara, who comes from work' },
    { time: '6:30 pm', seat: 'Long table in the back room', note: 'Quieter, good for talking' },
    { time: '7:00 pm', seat: 'Corner booth by the window', note: 'The original pick' },
    { time: '8:30 pm', seat: 'Corner booth by the window', note: 'Same booth, later evening' },
    { time: '9:15 pm', seat: 'Long table in the back room', note: 'Kitchen closes at 10:30 pm' }
  ];

  let chosen = $state(slots.findIndex((s) => s.time === booking.time));
  let pick = $derived(slots[chosen]);
  let isCurrent = $derived(pick.time === booking.time);
</script>

<Section title="Other times" kicker="Saffi & Rue · Sat, Nov 7 · 5 open slots for 6">
  <List>
    {#each slots as s, i}
      <ListRow
        index={i + 1}
        label={s.seat}
        sub={s.note}
        trailing={s.time}
        current={i === chosen}
        onclick={() => (chosen = i)}
      />
    {/each}
  </List>
  <p class="m-meta">Every slot is seated for 2 hours at the same $49 set menu.</p>
  {#snippet actions()}
    <Action
      label={isCurrent ? `Booked for ${pick.time}` : `Switch to ${pick.time}`}
      sublabel={isCurrent
        ? pick.seat
        : booking.reserved
          ? 'Moves your reservation, no fee'
          : 'Updates the booking above'}
      icon={isCurrent ? Check : Clock}
      primary
      disabled={isCurrent}
      onclick={() => {
        booking.time = pick.time;
        booking.seat = pick.seat;
      }}
    />
  {/snippet}
</Section>
```

